&lt;p&gt;🔒 &lt;strong&gt;Stay Safe from Job Scams&lt;/strong&gt;&lt;br&gt;All official Airtable communication will come from an &lt;strong&gt;@airtable.com&lt;/strong&gt; email address. We will never ask you to share sensitive information or purchase equipment during the hiring process. If in doubt, contact us at &lt;a href=&quot;mailto:hr@airtable.com&quot;&gt;hr@airtable.com&lt;/a&gt;. Learn more about avoiding job scams &lt;a href=&quot;https://consumer.ftc.gov/consumer-alerts/2022/05/want-work-home-spot-scams-first&quot;&gt;here&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;","departments":[{"id":4076814002,"name":"Data","child_ids":[],"parent_id":null}],"offices":[{"id":4026819002,"name":"Austin","location":"Austin, Texas, United States","child_ids":[],"parent_id":null},{"id":4005041002,"name":"New York","location":"New York, New York, United States","child_ids":[],"parent_id":null},{"id":4005133002,"name":"Remote - US","location":null,"child_ids":[],"parent_id":null},{"id":4005040002,"name":"San Francisco","location":"San Francisco, California, United States","child_ids":[],"parent_id":null}]}
